1	// Package github implements the GitHubWorkspaceAdapter interface.
2	// It uses the Git Trees API for feature discovery and the Contents API for
3	// individual file fetches — a single request discovers all feature paths,
4	// and only the relevant files are read. No archive download or zip extraction
5	// is required, and the same approach works for both full reconciliation and
6	// targeted sync.
7	package github
8	
9	import (
10		"context"
11		"fmt"
12		"net/url"
13		"os"
14		"strings"
15		"time"
16	
17		"github.com/tiendv89/workspace-github-adapter/internal/domain"
18	)
19	
20	// Adapter implements domain.GitHubWorkspaceAdapter.
21	type Adapter struct {
22		token string
23	}
24	
25	// New creates a new Adapter. If token is empty, the GITHUB_TOKEN environment
26	// variable is used as a fallback.
27	func New(token string) *Adapter {
28		if token == "" {
29			token = os.Getenv("GITHUB_TOKEN")
30		}
31		return &Adapter{token: token}
32	}
33	
34	// Ensure Adapter satisfies the interface at compile time.
35	var _ domain.GitHubWorkspaceAdapter = (*Adapter)(nil)
36	
37	// ImportWorkspace performs a full reconciliation import of the given repository.
38	func (a *Adapter) ImportWorkspace(ctx context.Context, input domain.ImportInput) (*domain.WorkspaceSnapshot, error) {
39		if err := validateInput(input); err != nil {
40			return nil, *err
41		}
42	
43		token := input.Token
44		if token == "" {
45			token = a.token
46		}
47		c := newClient(token)
48	
49		owner, repo, err := parseRepoURL(input.RepoURL)
50		if err != nil {
51			return nil, *err
52		}
53	
54		ref := input.DefaultBranch
55		if ref == "" {
56			ref = "main"
57		}
58	
59		return a.fetchSnapshot(ctx, c, owner, repo, ref, "")
60	}
61	
62	// SyncWorkspace re-fetches the repository at the given ref and returns an updated snapshot.
63	func (a *Adapter) SyncWorkspace(ctx context.Context, workspaceID, repoURL, ref string) (*domain.WorkspaceSnapshot, error) {
64		if repoURL == "" {
65			return nil, domain.NewValidationError(domain.ErrValidationMissingInput, "repoURL is required")
66		}
67		if ref == "" {
68			ref = "main"
69		}
70	
71		owner, repo, err := parseRepoURL(repoURL)
72		if err != nil {
73			return nil, *err
74		}
75	
76		c := newClient(a.token)
77		snap, fetchErr := a.fetchSnapshot(ctx, c, owner, repo, ref, workspaceID)
78		if fetchErr != nil {
79			return nil, fetchErr
80		}
81		return snap, nil
82	}
83	
84	// fetchSnapshot fetches the full workspace snapshot from GitHub.
85	func (a *Adapter) fetchSnapshot(ctx context.Context, c *client, owner, repo, ref, workspaceID string) (*domain.WorkspaceSnapshot, error) {
86		fetchedAt := time.Now().UTC()
87	
88		// Resolve the commit SHA for this ref.
89		commitSHA, err := c.getCommitSHA(ctx, owner, repo, ref)
90		if err != nil {
91			return nil, mapFetchError(err, owner, repo)
92		}
93	
94		// Fetch the full file tree in one request (Git Trees API, recursive=1).
95		tree, err := c.getTree(ctx, owner, repo, ref)
96		if err != nil {
97			return nil, mapFetchError(err, owner, repo)
98		}
99	
100		// Build a path-set for quick existence checks.
101		pathSet := make(map[string]struct{}, len(tree.Tree))
102		for _, e := range tree.Tree {
103			if e.Type == "blob" {
104				pathSet[e.Path] = struct{}{}
105			}
106		}
107	
108		// Fetch and parse workspace.yaml (required).
109		wsYAMLPath := "workspace.yaml"
110		wsData, err := c.getFileContent(ctx, owner, repo, wsYAMLPath, ref)
111		if err != nil {
112			return nil, mapFetchError(err, owner, repo)
113		}
114		if wsData == nil {
115			return nil, domain.SourceError{
116				Code:      domain.ErrGitHubNotFound,
117				Message:   fmt.Sprintf("required file not found: %s", wsYAMLPath),
118				Source:    domain.ErrorSourceGitHub,
119				Retryable: false,
120				Path:      wsYAMLPath,
121			}
122		}
123		wsCfg, parseErr := parseWorkspaceYAML(wsData, wsYAMLPath)
124		if parseErr != nil {
125			return nil, *parseErr
126		}
127	
128		// Discover feature directories from the tree.
129		featureIDs := discoverFeatureIDs(tree.Tree)
130	
131		// Map repos from workspace.yaml.
132		repos := make([]domain.RepoEntry, 0, len(wsCfg.Repos))
133		for _, r := range wsCfg.Repos {
134			repos = append(repos, domain.RepoEntry{
135				RepoID:     r.ID,
136				BaseBranch: r.BaseBranch,
137			})
138		}
139	
140		name := wsCfg.Name
141		if name == "" {
142			name = owner + "/" + repo
143		}
144		slug := slugify(name)
145		if workspaceID == "" {
146			workspaceID = slug
147		}
148	
149		var sourceErrors []domain.SourceError
150		features := make([]domain.FeatureSnapshot, 0, len(featureIDs))
151	
152		for _, featureID := range featureIDs {
153			feat, errs := a.fetchFeature(ctx, c, owner, repo, ref, featureID, pathSet)
154			sourceErrors = append(sourceErrors, errs...)
155			if feat != nil {
156				features = append(features, *feat)
157			}
158		}
159	
160		return &domain.WorkspaceSnapshot{
161			WorkspaceID:  workspaceID,
162			Name:         name,
163			Slug:         slug,
164			RepoURL:      "https://github.com/" + owner + "/" + repo,
165			CommitSHA:    commitSHA,
166			FetchedAt:    fetchedAt,
167			Features:     features,
168			Repos:        repos,
169			SourceErrors: sourceErrors,
170		}, nil
171	}
172	
173	// fetchFeature fetches and parses all artifacts for a single feature.
174	func (a *Adapter) fetchFeature(ctx context.Context, c *client, owner, repo, ref, featureID string, pathSet map[string]struct{}) (*domain.FeatureSnapshot, []domain.SourceError) {
175		var errs []domain.SourceError
176	
177		docPaths := featureDocPaths(featureID)
178		statusPath := docPaths["status_yaml"]
179	
180		// status.yaml is required — if missing, emit a source error.
181		statusData, err := c.getFileContent(ctx, owner, repo, statusPath, ref)
182		if err != nil {
183			errs = append(errs, asSourceError(err, statusPath))
184			return nil, errs
185		}
186		if statusData == nil {
187			errs = append(errs, domain.SourceError{
188				Code:      domain.ErrGitHubNotFound,
189				Message:   fmt.Sprintf("required file not found: %s", statusPath),
190				Source:    domain.ErrorSourceGitHub,
191				Retryable: false,
192				Path:      statusPath,
193			})
194			return nil, errs
195		}
196	
197		status, parseErr := parseFeatureStatusYAML(statusData, statusPath)
198		if parseErr != nil {
199			errs = append(errs, *parseErr)
200			return nil, errs
201		}
202	
203		// Build document links — only status.yaml has required content; the rest are optional.
204		docs := []domain.DocumentSnapshot{}
205		for docType, docPath := range docPaths {
206			_, exists := pathSet[docPath]
207			if exists || docType == "status_yaml" {
208				docs = append(docs, domain.DocumentSnapshot{
209					DocumentType: docType,
210					SourcePath:   docPath,
211					URL:          buildWebURL(owner, repo, ref, docPath),
212				})
213			}
214		}
215	
216		// Fetch all task YAMLs for this feature.
217		tasksDir := "docs/features/" + featureID + "/tasks/"
218		var taskSnapshots []domain.TaskSnapshot
219		for p := range pathSet {
220			if !strings.HasPrefix(p, tasksDir) {
221				continue
222			}
223			taskID := taskFileBase(p)
224			if taskID == "" {
225				continue
226			}
227			taskData, err := c.getFileContent(ctx, owner, repo, p, ref)
228			if err != nil {
229				errs = append(errs, asSourceError(err, p))
230				continue
231			}
232			if taskData == nil {
233				continue
234			}
235			taskParsed, parseErr := parseTaskYAML(taskData, p)
236			if parseErr != nil {
237				errs = append(errs, *parseErr)
238				continue
239			}
240	
241			taskSnap := mapTaskSnapshot(taskParsed, featureID, taskID, p, taskData)
242			taskSnapshots = append(taskSnapshots, taskSnap)
243		}
244	
245		// Map feature history to activity events.
246		activity := mapActivityLog(status.History, "feature", featureID, "")
247	
248		return &domain.FeatureSnapshot{
249			FeatureID:    featureID,
250			Title:        status.Title,
251			Status:       status.Status,
252			CurrentStage: status.Stage,
253			NextAction:   status.NextAction,
254			SourcePath:   statusPath,
255			SourceHash:   hashContent(statusData),
256			Documents:    docs,
257			Tasks:        taskSnapshots,
258			Activity:     activity,
259		}, errs
260	}
261	
262	// mapTaskSnapshot converts a parsed taskYAML to a domain.TaskSnapshot.
263	func mapTaskSnapshot(t *taskYAML, featureID, taskID, sourcePath string, rawData []byte) domain.TaskSnapshot {
264		var activity []domain.ActivityEvent
265		if len(t.Log) > 0 {
266			activity = mapActivityLog(t.Log, "task", featureID, taskID)
267		}
268	
269		return domain.TaskSnapshot{
270			TaskID:        taskID,
271			FeatureID:     featureID,
272			Title:         t.Title,
273			Status:        t.Status,
274			Repo:          t.Repo,
275			Branch:        t.Branch,
276			DependsOn:     t.DependsOn,
277			BlockedReason: blockedReasonString(t.BlockedReason),
278			Execution:     t.Execution,
279			PR:            t.PR,
280			WorkspacePR:   t.WorkspacePR,
281			SourcePath:    sourcePath,
282			SourceHash:    hashContent(rawData),
283			Activity:      activity,
284		}
285	}
286	
287	// discoverFeatureIDs scans the tree entries for docs/features/*/status.yaml paths
288	// and returns the unique feature IDs found.
289	func discoverFeatureIDs(entries []treeEntry) []string {
290		seen := make(map[string]struct{})
291		var ids []string
292		for _, e := range entries {
293			if e.Type != "blob" {
294				continue
295			}
296			featureID, ok := extractFeatureID(e.Path)
297			if !ok {
298				continue
299			}
300			if _, dup := seen[featureID]; dup {
301				continue
302			}
303			seen[featureID] = struct{}{}
304			ids = append(ids, featureID)
305		}
306		return ids
307	}
308	
309	// validateInput checks ImportInput for required fields.
310	func validateInput(input domain.ImportInput) *domain.SourceError {
311		if input.RepoURL == "" {
312			se := domain.NewValidationError(domain.ErrValidationMissingInput, "RepoURL is required")
313			return &se
314		}
315		return nil
316	}
317	
318	// parseRepoURL extracts the owner and repo name from a GitHub URL.
319	// Accepts https://github.com/owner/repo and git@github.com:owner/repo.git forms.
320	func parseRepoURL(rawURL string) (owner, repo string, se *domain.SourceError) {
321		rawURL = strings.TrimSpace(rawURL)
322	
323		// SSH form: git@github.com:owner/repo.git
324		if strings.HasPrefix(rawURL, "git@github.com:") {
325			rest := strings.TrimPrefix(rawURL, "git@github.com:")
326			rest = strings.TrimSuffix(rest, ".git")
327			parts := strings.SplitN(rest, "/", 2)
328			if len(parts) != 2 || parts[0] == "" || parts[1] == "" {
329				se = ptr(domain.NewValidationError(domain.ErrValidationInvalidURL,
330					fmt.Sprintf("invalid GitHub SSH URL: %s", rawURL)))
331				return
332			}
333			return parts[0], parts[1], nil
334		}
335	
336		// HTTPS form.
337		u, err := url.Parse(rawURL)
338		if err != nil || u.Host != "github.com" {
339			se = ptr(domain.NewValidationError(domain.ErrValidationInvalidURL,
340				fmt.Sprintf("invalid GitHub URL: %s", rawURL)))
341			return
342		}
343		parts := strings.Split(strings.Trim(u.Path, "/"), "/")
344		if len(parts) < 2 || parts[0] == "" || parts[1] == "" {
345			se = ptr(domain.NewValidationError(domain.ErrValidationInvalidURL,
346				fmt.Sprintf("GitHub URL must include owner and repo: %s", rawURL)))
347			return
348		}
349		return parts[0], strings.TrimSuffix(parts[1], ".git"), nil
350	}
351	
352	func ptr(se domain.SourceError) *domain.SourceError { return &se }
353	
354	// mapFetchError converts a repo-level fetch error to a SourceError, adding repo context.
355	func mapFetchError(err error, owner, repo string) error {
356		if se, ok := err.(domain.SourceError); ok {
357			if se.Code == domain.ErrGitHubNotFound {
358				return domain.NewGitHubNotFoundError("https://github.com/" + owner + "/" + repo)
359			}
360		}
361		return err
362	}
363	
364	// asSourceError coerces any error to a domain.SourceError, adding path context.
365	func asSourceError(err error, path string) domain.SourceError {
366		if se, ok := err.(domain.SourceError); ok {
367			se.Path = path
368			return se
369		}
370		return domain.SourceError{
371			Code:      domain.ErrAdapterInternal,
372			Message:   err.Error(),
373			Source:    domain.ErrorSourceAdapter,
374			Retryable: false,
375			Path:      path,
376		}
377	}
378

