389	// proxyTransport returns an http.RoundTripper that rewrites requests to the given base URL.
390	func proxyTransport(baseURL string) http.RoundTripper {
391		return &rewriteTransport{base: baseURL}
392	}
393	
394	type rewriteTransport struct {
395		base string
396	}
397	
398	func (t *rewriteTransport) RoundTrip(req *http.Request) (*http.Response, error) {
399		// Replace the host with the test server, keep the path+query.
400		req2 := req.Clone(req.Context())
401		req2.URL.Scheme = "http"
402		base := strings.TrimSuffix(t.base, "/")
403		// Extract path from base to use as server address.
404		hostPort := strings.TrimPrefix(base, "http://")
405		req2.URL.Host = hostPort
406		return http.DefaultTransport.RoundTrip(req2)
407	}
